const result = (q, answer, unit, hint, solution, wrong, feedback) => ({q, answer: Math.round(answer * 100) / 100, unit, hint, solution, wrong: Math.round(wrong * 100) / 100, feedback});
const n = (s, mod, offset = 0) => Math.abs(Math.trunc(s)) % mod + offset;
export const course = {
  title: '1P',
  intro: 'Matematikk 1P handler om å bruke matematikk kritisk i samfunns- og arbeidsliv. Her møter du forklaringer, utforskende aktiviteter og oppgaver på tre nivåer. Vis fremgangsmåte og vurder om resultatet passer med situasjonen.',
  source: 'https://www.udir.no/lk20/mat08-01/kompetansemaal-og-vurdering/kv31?lang=nob',
  chapters: [
    {
      id:'lokalmiljo', title:'Matematikk i lokalmiljøet', summary:'Les tall kritisk, regn og argumenter med lokale tekster.',
      theory:['En lokal tekst kan inneholde absolutte tall, andeler og sammenligninger. Noter hva tallene gjelder, tidsrom, enheter og om utvalget er representativt før du regner.', 'En prosentandel trenger en nevner. Når to perioder har ulikt antall observasjoner, kan en sammenligning av antall gi et annet inntrykk enn en sammenligning av andeler. Undersøk kilde, manglende opplysninger og alternative forklaringer.'],
      example:['Fiktivt skoleavisutdrag: «I uke 1 syklet 120 av 400 elever til skolen. I uke 2 syklet 144 av 480.»','Uke 1: 120/400 · 100 = 30 %. Uke 2: 144/480 · 100 = 30 %.','Antallet økte med 24, men andelen er uendret. Vi vet ikke om de samme elevene svarte eller hvordan tellingene ble gjort.'],
      activity:'Finn en aktuell lokal tekst med tall, for eksempel om transport eller avfall. Oppgi lenke, dato og relevante tall. Regn ut minst to størrelser, presenter en tabell eller figur, og vurder hva tallene faktisk gir grunnlag for å hevde. Forklar én alternativ tolkning og én opplysning du savner.',
      criteria:['Kilden og tallgrunnlaget kan etterprøves.','Beregninger, enheter og representasjon er tydelige.','Konklusjonen begrunnes og begrensninger drøftes.'],
      model:'I det fiktive skoleavisutdraget er andelen syklister 30 % begge uker. Antallet steg med 20 %, men dette viser ikke at en større andel syklet. Jeg ville undersøkt om tellingene dekket de samme elevene og om været var ulikt.',
      teacher:'Forkunnskaper: brøk og prosent. Vanlig feil: tolke endring i antall som endring i andel. Spør: Hvem er med i nevneren, og hva ville endret konklusjonen?',
      goals:['Lese, vurdere og beregne ut fra lokale tekster; presentere og argumentere.'],
      task(level,seed){let a=n(seed,8,12)*10,b=n(seed,5,4)*100;if(level===0)return result(`En fiktiv lokal undersøkelse viser at ${a} av ${b} elever sykler. Hvor mange prosent er dette? Avrund til to desimaler.`,100*a/b,'%', 'Del antall syklister på totalt antall og gang med 100.',`${a}/${b} · 100 = ${(100*a/b).toFixed(2)} %.`,a/b,'Du fant brøken; gang med 100 for prosent.');if(level===1){let x=n(seed,6,3)*10,y=x+20;return result(`I en fiktiv telling sykler ${x} av 200 første uke og ${y} av 200 neste uke. Hvor mange prosentpoeng øker andelen?`,10,'prosentpoeng','Finn begge prosentandelene og trekk fra.',`Økningen er 20/200 · 100 = 10 prosentpoeng.`,20,'20 er økningen i antall, ikke prosentpoeng.');}let x=n(seed,8,11)*10;return result(`En fiktiv lokal rapport oppgir ${x} reisende i fjor og ${x+30} i år. Hvor stor er økningen i prosent av fjorårets tall? Avrund til to desimaler.`,3000/x,'%', 'Bruk fjorårets tall som grunnlag.',`30/${x} · 100 = ${(3000/x).toFixed(2)} %.`,30,'30 er økningen i antall.');}
    },
    {
      id:'prosent',title:'Prosent, prosentpoeng og promille',summary:'Velg riktig grunnlag og beskriv endring presist.',
      theory:['Prosent betyr hundredeler og promille tusendeler. Andel = del/helt, mens delen finnes ved å multiplisere helheten med andelen skrevet som desimaltall.', 'Prosentpoeng er differansen mellom to prosentandeler. Relativ prosentvis endring er differansen delt på den opprinnelige andelen. 20 % til 25 % er 5 prosentpoeng, men 25 % relativ økning.'],
      example:['En pris på 800 kr øker med 15 %: økningen er 0,15 · 800 = 120 kr.','Ny pris er 920 kr. En feilandel på 3 ‰ av 4000 varer er 0,003 · 4000 = 12 varer.'],
      activity:'En skole har 600 elever. Andelen som tar buss går fra 40 % til 46 %. Samtidig viser en kontroll 5 feil per 1000 bussbilletter. Beregn antall bussreisende før og etter, endring i prosentpoeng og relativ prosent, samt feil per 2000 billetter. Diskuter hvilke antakelser som ligger bak.',
      criteria:['Skiller mellom relativ endring og prosentpoeng.','Bruker riktige grunnlag og enheter.','Forklarer forutsetningen om likt elevtall.'],
      model:'240 og 276 elever gir 36 flere, forutsatt 600 elever begge ganger. Endringen er 6 prosentpoeng og 6/40 = 15 % relativt. 5 ‰ av 2000 er 10 feil hvis feilraten er representativ.',
      teacher:'Forkunnskaper: brøk og desimaltall. Spør hvorfor 6 prosentpoeng ikke er 6 prosent relativ økning. La elever vise andeler med rutenett.',
      goals:['Bruke og begrunne prosent, prosentpoeng og promille.'],
      task(level,seed){let x=n(seed,15,10),total=n(seed,8,2)*100;if(level===0)return result(`Hva er ${x} % av ${total} kr?`,x*total/100,'kr','Gjør prosent om til desimaltall.',`${x}/100 · ${total} = ${x*total/100} kr.`,x+total,'Prosentandelen skal multipliseres med grunnlaget.');if(level===1){let a=n(seed,20,20),d=n(seed,9,2);return result(`En andel øker fra ${a} % til ${a+d} %. Hvor mange prosentpoeng er økningen?`,d,'prosentpoeng','Trekk den første prosentandelen fra den andre.',`${a+d} − ${a} = ${d} prosentpoeng.`,100*d/a,'Dette er relativ prosentvis endring, ikke prosentpoeng.');}let p=n(seed,7,2),m=n(seed,8,2)*1000;return result(`En feilrate er ${p} ‰ av ${m} varer. Hvor mange varer svarer dette til?`,p*m/1000,'varer','Promille betyr per tusen.',`${p}/1000 · ${m} = ${p*m/1000} varer.`,p*m/100,'Del på 1000, ikke 100.');}
    },
    {
      id:'vekstfaktor',title:'Vekstfaktor og gjentatt endring',summary:'Modeller prosentvis vekst, nedgang og reversering.',
      theory:['Vekstfaktoren er 1 + p/100 ved p prosent økning og 1 − p/100 ved nedgang. Ny verdi = gammel verdi · vekstfaktor.', 'Ved gjentatt endring multipliseres vekstfaktorene. Like stor prosentvis økning og nedgang opphever ikke hverandre fordi grunnlaget endres. For å finne gammel verdi deler vi på vekstfaktoren.'],
      example:['En vare koster 1000 kr, øker 20 % og settes deretter ned 20 %.','1000 · 1,20 · 0,80 = 960 kr. Samlet endring er 4 % nedgang, ikke null.'],
      activity:'Undersøk en pris på 2000 kr som først øker 10 % og så settes ned 10 %. Sammenlign med motsatt rekkefølge og med to påfølgende økninger. Lag tabell og uttrykk, og forklar hvorfor sluttverdiene blir som de blir.',
      criteria:['Bruker vekstfaktorer korrekt.','Sammenligner minst tre forløp med tabell og uttrykk.','Begrunner effekten av endret grunnlag.'],
      model:'2000 · 1,10 · 0,90 = 1980 kr. Motsatt rekkefølge gir samme produkt og samme verdi. To økninger gir 2000 · 1,10² = 2420 kr.',
      teacher:'Forkunnskaper: prosentregning. Vanlig feil: legge sammen prosentsatser ukritisk. Spør: Hvilket beløp er grunnlag for hver endring?',
      goals:['Bruke vekstfaktor og begrunne prosentberegninger.','Modellere og vurdere gyldighet.'],
      task(level,seed){let p=n(seed,9,2)*5,x=n(seed,9,2)*100;if(level===0)return result(`En pris er ${x} kr og øker ${p} %. Hva blir ny pris?`,x*(1+p/100),'kr','Bruk vekstfaktor 1 + p/100.',`${x} · ${1+p/100} = ${x*(1+p/100)} kr.`,x*p/100,'Dette er økningen, ikke den nye prisen.');if(level===1)return result(`En pris på ${x} kr synker ${p} % to ganger. Finn sluttprisen, avrundet til to desimaler.`,x*(1-p/100)**2,'kr','Multipliser med nedgangsfaktoren to ganger.',`${x} · ${(1-p/100).toFixed(2)}² = ${(x*(1-p/100)**2).toFixed(2)} kr.`,x*(1-2*p/100),'Andre nedgang regnes av den nye prisen.');let v=n(seed,9,2)*100;return result(`Etter en økning på ${p} % er prisen ${Math.round(v*(1+p/100)*100)/100} kr. Hva var prisen før økningen?`,v,'kr','Del sluttprisen på vekstfaktoren.',`${Math.round(v*(1+p/100)*100)/100} / ${1+p/100} = ${v} kr.`,v*(1+p/100)*(1-p/100),'Å redusere sluttprisen med samme prosent reverserer ikke økningen.');}
    },
    {
      id:'proporsjonalitet',title:'Proporsjonal og omvendt proporsjonal',summary:'Kjenn igjen sammenhenger gjennom tabell, formel og graf.',
      theory:['Ved proporsjonalitet er y = kx og forholdet y/x konstant når x ≠ 0. Grafen er en rett linje gjennom origo. Dobles x, dobles y.', 'Ved omvendt proporsjonalitet er y = k/x for x ≠ 0, og produktet xy er konstant. Dobles x, halveres y. For eksempel forutsetter arbeidstid og antall arbeidere lik effektivitet og fast arbeidsmengde.'],
      example:['Tre kg epler koster 90 kr med fast kilopris. k = 90/3 = 30 kr/kg, så prisen er y = 30x.','Et arbeid krever 24 persontimer. Med 4 like effektive arbeidere blir tiden 24/4 = 6 timer.'],
      activity:'Sammenlign en kopitjeneste som tar 2 kr per side med en tjeneste som tar 40 kr i oppstart og 1 kr per side. Lag verditabell, uttrykk og graf for 0–100 sider. Finn skjæringspunktet og vurder hvilke sammenhenger som er proporsjonale.',
      criteria:['Uttrykk, tabell og graf stemmer sammen.','Skjæringspunktet tolkes i kontekst.','Proporsjonalitet begrunnes med konstant forhold eller origo.'],
      model:'Prisene er A(x)=2x og B(x)=40+x. Ved x=40 koster begge 80 kr. A er proporsjonal; B har startpris og går ikke gjennom origo. For flere enn 40 sider er B billigst.',
      teacher:'Forkunnskaper: forhold og koordinatsystem. Feil: alle rette linjer er proporsjonale. Spør hva som skjer når x=0 og hvilke arbeidsforhold som kan bryte modellen.',
      goals:['Utforske og bruke proporsjonalitet og omvendt proporsjonalitet.','Identifisere variable størrelser og generalisere.'],
      task(level,seed){let k=n(seed,9,2),x=n(seed,9,2);if(level===0)return result(`En vare koster ${k} kr per enhet. Hva koster ${x} enheter ved fast pris?`,k*x,'kr','Multipliser antall med enhetspris.',`${k} · ${x} = ${k*x} kr.`,k*x+k,'Antallet er én for høyt i dette svaret.');if(level===1){let a=n(seed,8,2),b=n(seed,8,2),t=a*b;return result(`${a} like effektive arbeidere bruker ${b} timer. Hvor mange timer bruker ${a*2} arbeidere på samme arbeid?`,b/2,'timer','Arbeidsmengden er konstant; dobbelt så mange halverer tiden.',`${a} · ${b} / ${a*2} = ${b/2} timer.`,b*2,'Flere arbeidere gir her kortere tid.');}let fixed=n(seed,5,2)*10,rate=n(seed,4,2);return result(`Firma A tar ${rate+1} kr per side. Firma B tar ${fixed} kr i oppstart og ${rate} kr per side. Ved hvor mange sider er prisene like?`,fixed,'sider','Sett prisuttrykkene lik hverandre.',`${rate+1}x = ${fixed} + ${rate}x gir x = ${fixed}.`,fixed/(rate+1),'Husk at også firma B har en pris per side.');}
    },
    {
      id:'enheter',title:'Sammensatte måleenheter',summary:'Bruk og omregn fart, tetthet og forbruk.',
      theory:['En sammensatt måleenhet uttrykker et forhold mellom størrelser, for eksempel km/t, kr/kg eller kWh per døgn. Enheten viser hva som er teller og nevner.', 'Ved omregning må begge deler av enheten håndteres. 1 m/s = 3,6 km/t fordi én meter er 0,001 km og ett sekund er 1/3600 time. Velg enheter som passer presisjonen og sammenhengen.'],
      example:['En bil kjører 150 km på 2 timer og 30 minutter. 30 minutter = 0,5 timer.','Gjennomsnittsfarten er 150/2,5 = 60 km/t. Dette sier ikke at farten var konstant.'],
      activity:'Planlegg en 180 km reise. Sammenlign en bil som bruker 0,18 kWh/km med en bil som bruker 0,22 kWh/km. Bruk to selvvalgte energipriser i kr/kWh, beregn kostnader og forklar hvordan kulde eller kjørestil kan påvirke svaret.',
      criteria:['Enheter forkortes og tolkes korrekt.','To prisforutsetninger undersøkes.','Praktiske begrensninger forklares.'],
      model:'Bilene bruker 32,4 og 39,6 kWh. Ved 2 kr/kWh koster dette 64,80 og 79,20 kr; ved 3 kr/kWh 97,20 og 118,80 kr. Faktisk forbruk kan avvike blant annet på grunn av temperatur.',
      teacher:'Forkunnskaper: enhetsomregning og divisjon. Vanlig feil: 2 t 30 min = 2,30 t. Spør hvilken størrelse enheten beskriver og om gjennomsnitt innebærer konstant fart.',
      goals:['Tolke og bruke sammensatte måleenheter og velge enhet.'],
      task(level,seed){let km=n(seed,9,4)*30,t=n(seed,3,2);if(level===0)return result(`En tur er ${km} km og tar ${t} timer. Hva er gjennomsnittsfarten?`,km/t,'km/t','Fart = strekning / tid.',`${km}/${t} = ${km/t} km/t.`,km*t,'Del strekningen på tiden.');if(level===1){let v=n(seed,15,5);return result(`Gjør om ${v} m/s til km/t.`,v*3.6,'km/t','Multipliser m/s med 3,6.',`${v} · 3,6 = ${v*3.6} km/t.`,v/3.6,'Fra m/s til km/t multipliserer vi med 3,6.');}let d=n(seed,8,2)*50,c=n(seed,5,2)/10,price=n(seed,5,2);return result(`En bil kjører ${d} km og bruker ${c} kWh/km. Strømmen koster ${price} kr/kWh. Hva koster energien?`,d*c*price,'kr','Finn først energibruken i kWh.',`${d} · ${c} · ${price} = ${d*c*price} kr.`,d*c,'Dette er energibruken i kWh, ikke kostnaden.');}
    },
    {
      id:'variabler',title:'Variabler, mønster og generalisering',summary:'Beskriv hvordan størrelser varierer sammen.',
      theory:['En variabel representerer en størrelse som kan variere. Skill mellom uavhengig variabel, som velges eller observeres, og avhengig variabel, som beregnes eller måles.', 'En tabell kan avsløre konstant differanse og foreslå en lineær modell y = ax + b. a er endring per enhet x, mens b er startverdien. En rett linje gjennom origo er et spesialtilfelle med b = 0.'],
      example:['En sykkelutleie koster 50 kr i startgebyr og 20 kr per time. La x være timer og y pris i kroner.','y = 20x + 50. For x = 3 er y = 110. Tabellen (0,50), (1,70), (2,90) har konstant differanse 20.'],
      activity:'En utleier tar 60 kr i startgebyr og 25 kr per time. Lag tabell for 0–6 timer, tegn graf og skriv et generelt uttrykk. Finn når prisen når 185 kr, og drøft om modellen gjelder for en halv time og for en uke.',
      criteria:['Definerer variabler og enheter.','Kobler uttrykk, tabell og graf.','Løser og vurderer tidsbegrensning og betalingsregler.'],
      model:'P(x)=60+25x. P(0)=60, P(1)=85 og P(5)=185. Ved 5 timer når prisen 185 kr. Halvtimer forutsetter betaling per faktisk time, og ukepris kan ha rabatt som modellen ikke beskriver.',
      teacher:'Forkunnskaper: regnerekkefølge og koordinater. Feil: forveksle stigningstall og konstantledd. Spør hva pris ved null timer og differansen per time betyr.',
      goals:['Identifisere variable størrelser og bruke dem til utforsking og generalisering.','Tolke og bruke formler.'],
      task(level,seed){let a=n(seed,8,2),b=n(seed,8,2)*10,x=n(seed,6,2);if(level===0)return result(`Prisen er P(x) = ${a}x + ${b} kroner. Hva er prisen for x = ${x}?`,a*x+b,'kr','Sett inn x og multipliser før du legger til.',`${a} · ${x} + ${b} = ${a*x+b} kr.`,a*x,'Husk også konstantleddet.');if(level===1)return result(`En pris er ${b} kr ved 0 timer og ${b+a*2} kr ved 2 timer. Prisen er lineær. Hva er økningen per time?`,a,'kr/time','Del endringen i pris på endringen i tid.',`(${b+a*2} − ${b})/2 = ${a} kr/time.`,b,'Startpris er ikke økning per time.');return result(`Kostnaden er K(x) = ${a}x + ${b} kr. Hvor mange enheter gir en kostnad på ${a*x+b} kr?`,x,'enheter','Trekk fra startbeløpet og del på prisen per enhet.',`(${a*x+b} − ${b})/${a} = ${x}.`,(a*x+b)/a,'Trekk først fra konstantleddet.');}
    },
    {
      id:'formler',title:'Formler i arbeidsliv og samfunn',summary:'Tolk, bruk og omform formler med kontroll av enheter.',
      theory:['En formel viser en sammenheng mellom størrelser. Identifiser hva symbolene betyr og hvilke enheter formelen krever før du setter inn verdier.', 'Samme operasjon på begge sider bevarer en likhet. Omform for å isolere en ukjent, og kontroller ved å sette svaret tilbake. Formler bygger på forutsetninger og er ikke nødvendigvis gyldige i alle situasjoner.'],
      example:['Lønn L = t · s, der t er timer og s er timelønn. Ved 7,5 timer og 220 kr/time er L = 1650 kr.','Hvis L = 1650 og s = 220, er t = L/s = 7,5 timer. Kontroll: 7,5 · 220 = 1650.'],
      activity:'Et oppdrag betales etter L = 240t + 500, der t er timer og L er kroner. Beregn lønn for 3, 5 og 8 timer. Finn antall timer for 1940 kr. Beskriv hvilke forhold formelen ikke fanger opp, og lag en alternativ modell med overtidsbetaling.',
      criteria:['Forklarer symboler og enheter.','Bruker og omformer formelen korrekt.','Begrunner den alternative modellen og dens premisser.'],
      model:'For 3, 5 og 8 timer er lønnen 1220, 1700 og 2420 kr. (1940 − 500)/240 = 6 timer. Med 50 % tillegg etter 8 timer kan L=500+240t for t≤8 og L=2420+360(t−8) for t>8.',
      teacher:'Forkunnskaper: likninger og regnerekkefølge. Feil: dividere hele beløpet med timesats før fast tillegg er trukket fra. Spør om modellen beskriver brutto eller netto lønn.',
      goals:['Tolke og bruke formler fra samfunns- og arbeidsliv.','Utforske hvordan premisser påvirker løsninger.'],
      task(level,seed){let t=n(seed,7,2),s=n(seed,8,15)*10,b=n(seed,5,1)*100;if(level===0)return result(`Lønn er L = t · s. Du arbeider ${t} timer med ${s} kr/time. Finn L.`,t*s,'kr','Multipliser tid med timesats.',`${t} · ${s} = ${t*s} kr.`,t+s,'Timer og timesats skal multipliseres.');if(level===1)return result(`L = ${s}t + ${b}. Hvor stor er lønnen for ${t} timer?`,s*t+b,'kr','Beregn timelønn først, og legg til fastbeløpet.',`${s} · ${t} + ${b} = ${s*t+b} kr.`,s*t,'Fastbeløpet mangler.');return result(`L = ${s}t + ${b}. Lønnen er ${s*t+b} kr. Finn t.`,t,'timer','Trekk fra fastbeløpet og del på timesatsen.',`t = (${s*t+b} − ${b})/${s} = ${t} timer.`,(s*t+b)/s,'Trekk fra fastbeløpet før du deler.');}
    },
    {
      id:'modellering',title:'Modellering og premisser',summary:'Lag modeller, prøv dem mot data og vurder gyldighet.',
      theory:['Modellering starter med et spørsmål og en forenkling av virkeligheten. Definer variabler, angi forutsetninger og velg en sammenheng som kan undersøkes med data.', 'En modell kan passe observerte data uten å være gyldig overalt. Sammenlign modell og observasjoner, undersøk følsomhet for premisser og vurder definisjonsområde. Interpolasjon innenfor dataintervallet er ofte tryggere enn ekstrapolasjon utenfor, men gir ingen garanti.'],
      example:['Fiktive data for produksjon: 0 timer: 20 enheter, 1 time: 32, 2 timer: 44, 3 timer: 55.','En enkel modell er P(t)=20+12t. Ved 3 timer gir modellen 56, én mer enn observert. Startlager og tilnærmet konstant produksjonsrate er premisser.'],
      activity:'Bruk de fiktive produksjonsdataene 20, 32, 44 og 55 enheter etter 0, 1, 2 og 3 timer. Lag en lineær modell, tabell med avvik og graf. Anslå etter 2,5 og 10 timer; sammenlign sikkerheten og undersøk hvordan en lavere timeproduksjon endrer anslaget.',
      criteria:['Definerer variabler og begrunner modellvalg.','Sammenligner modell og data med avvik.','Drøfter premisser, gyldighetsområde og usikkerhet.'],
      model:'P(t)=20+12t gir 20, 32, 44 og 56. Avviket modell minus observasjon er 0, 0, 0 og 1. Modellen gir 50 ved 2,5 timer og 140 ved 10 timer. Det siste er en langt mer usikker ekstrapolasjon; ved 10 enheter per time blir anslaget 120.',
      teacher:'Forkunnskaper: lineære uttrykk og tabeller. Feil: anta at god tilpasning garanterer sikker ekstrapolasjon. Spør hvordan pauser, kapasitet eller startlager påvirker modellen.',
      goals:['Modellere samfunns- og arbeidsliv og argumentere for gyldighet.','Utforske konsekvenser av ulike premisser.'],
      task(level,seed){let b=n(seed,7,2)*10,a=n(seed,8,2),t=n(seed,5,2);if(level===0)return result(`En modell er P(t) = ${b} + ${a}t enheter. Finn modellverdien etter ${t} timer.`,b+a*t,'enheter','Sett inn t i modellen.',`${b} + ${a} · ${t} = ${b+a*t}.`,a*t,'Husk startverdien.');if(level===1){let obs=b+a*t-3;return result(`Modellen P(t) = ${b} + ${a}t gir en prognose. Etter ${t} timer observeres ${obs} enheter. Finn avviket modell minus observasjon.`,3,'enheter','Beregn modellverdien og trekk fra observasjonen.',`${b+a*t} − ${obs} = 3 enheter.`,obs-(b+a*t),'Her er avvik definert som modell minus observasjon.');}let c=a+2;return result(`To modeller er P(t) = ${b} + ${a}t og Q(t) = ${b} + ${c}t. Hvor mange flere enheter gir Q etter ${t} timer?`,2*t,'enheter','Sammenlign endringsratene; startverdiene er like.',`Q(${t}) − P(${t}) = (${c} − ${a}) · ${t} = ${2*t}.`,c-a,'Forskjellen per time må multipliseres med antall timer.');}
    }
 ,
    {
      id:'funksjoner', title:'Funksjoner og digitale verktøy', summary:'Bruk funksjoner til å modellere, sammenligne og undersøke samfunnsforhold.',
      theory:['En funksjon gir nøyaktig én funksjonsverdi for hver tillatt verdi av den uavhengige variabelen. Definisjonsmengden beskriver hvilke x-verdier modellen gjelder for; verdimengden beskriver tilhørende y-verdier.', 'Digitale verktøy kan tegne grafer, beregne nullpunkter og skjæringspunkter og undersøke vekst. Et nullpunkt er der funksjonsverdien er null; et skjæringspunkt mellom to grafer betyr at funksjonene har lik verdi. Kontroller at svarene gir mening innenfor modellens definisjonsmengde.', 'En lineær modell har konstant endring per enhet, mens en eksponentiell modell har konstant vekstfaktor. Sammenlign modeller mot observasjoner og vurder om forutsetningene er rimelige.'],
      example:['To fiktive abonnement koster A(x)=50+2x og B(x)=110+x kroner for x GB, der 0 ≤ x ≤ 100.','I et grafverktøy tegner vi begge funksjonene på intervallet. Skjæringspunktet er (60,170): ved 60 GB koster begge 170 kr.','Kontroll: 50+2·60=170 og 110+60=170. Under 60 GB er A billigere, over 60 GB er B billigere innenfor intervallet.'],
      activity:'Planlegg og gjennomfør et selvstendig prosjekt om et samfunnstema, for eksempel transport, energiforbruk eller abonnement. Finn og oppgi en etterprøvbar datakilde og minst fire datapunkter, eller samle egne data og beskriv metoden. Lag minst to funksjonsmodeller med digitale verktøy, vis data og grafer i samme koordinatsystem, og sammenlign avvik og relevante egenskaper. Angi variabler, enheter, definisjonsmengde og premisser. Presenter en begrunnet anbefaling med tabell, graf og kort muntlig eller skriftlig forklaring. Drøft usikkerhet, modellens gyldighet og hva som skjer dersom et sentralt premiss endres.',
      criteria:['Prosjektet har et tydelig spørsmål, datakilde og dokumentert arbeidsmåte.','Digitale grafer og beregninger brukes til å sammenligne funksjonsegenskaper og data.','Konklusjon og modellens gyldighetsområde begrunnes med premisser og usikkerhet.'],
      model:'Et mulig prosjekt sammenligner fiktive abonnement A(x)=50+2x og B(x)=110+x, 0–100 GB. Grafene skjærer hverandre ved (60,170), kontrollert ved innsetting. A er billigst før 60 GB og B etterpå. Anbefalingen gjelder bare innenfor intervallet og forutsetter at gebyrer, priser og bruksmønster er stabile. Et prosjekt med faktiske data må oppgi kilde og sammenligne modellene med observasjoner.',
      teacher:'Forkunnskaper: koordinater og uttrykk. Elevene kan bruke regneark eller graftegner. Feil: tolke alle skjæringspunkter som relevante selv utenfor definisjonsmengden. Spør hva aksene betyr, hvordan data er samlet og hva endrede premisser gjør med anbefalingen.',
      goals:['Bruke funksjoner i modellering og vurdere modellenes gyldighet.','Planlegge, utføre og presentere selvstendig arbeid om modellering og funksjoner i samfunnsfaglige temaer.','Bruke digitale verktøy til å undersøke egenskaper ved funksjoner.'],
      task(level,seed){let a=n(seed,7,2),b=n(seed,7,2)*10,x=n(seed,8,2);if(level===0)return result(`Funksjonen f(x) = ${a}x + ${b}. Finn f(${x}).`,a*x+b,'','Sett inn x i funksjonsuttrykket.',`f(${x}) = ${a} · ${x} + ${b} = ${a*x+b}.`,a*x,'Konstantleddet må være med.');if(level===1)return result(`To abonnement har prisene A(x) = ${a+1}x + ${b} og B(x) = ${a}x + ${b+30}, der 0 ≤ x ≤ 100. Ved hvilken x er prisene like?`,30,'enheter','Sett funksjonsuttrykkene lik hverandre.',`${a+1}x + ${b} = ${a}x + ${b+30} gir x = 30.`,b+30,'Skjæringspunktets x-verdi er antallet enheter, ikke et konstantledd.');return result(`Funksjonen f(x) = ${a}x − ${a*x} er definert for 0 ≤ x ≤ 100. Finn nullpunktet.`,x,'','Sett f(x) = 0 og løs likningen.',`${a}x − ${a*x} = 0 gir x = ${x}.`,a*x,'Nullpunktet er x-verdien der funksjonen er null.');}
    },
    {
      id:'potenser', title:'Potenser, røtter og standardform', summary:'Regn med svært store og små tall og vurder størrelsesorden.',
      theory:['En potens aⁿ er produktet av n like faktorer a når n er et positivt heltall. For a ≠ 0 er a⁰ = 1 og a⁻ⁿ = 1/aⁿ. Ved multiplikasjon av potenser med samme grunntall legger vi sammen eksponentene; ved divisjon trekker vi dem fra.', 'Kvadratroten √a er det ikke-negative tallet som ganget med seg selv gir a, når a ≥ 0. Likningen x² = a har to løsninger ±√a når a > 0, selv om √a betegner den positive roten.', 'Standardform er a · 10ⁿ der 1 ≤ |a| < 10 og n er et heltall. Den gjør størrelsesorden synlig og passer for eksempel når avstander, datamengder eller partikkelstørrelser skal sammenlignes.'],
      example:['0,000045 = 4,5 · 10⁻⁵ og 3 000 000 = 3 · 10⁶.','(4,5 · 10⁻⁵)(3 · 10⁶) = 13,5 · 10¹ = 1,35 · 10² = 135.','√144 = 12. Kontroll: 12² = 144; likningen x² = 144 har løsningene x = 12 og x = −12.'],
      activity:'En kvadratisk solcelleflate har areal 2,25 · 10⁴ cm². Finn sidelengden i cm og m, og regn arealet om til m² på standardform. Anta deretter at sidekantene dobles: finn nytt areal og forklar hvorfor det ikke bare dobles. Vis beregning og kontroll.',
      criteria:['Bruker røtter og tierpotenser korrekt.','Omregner lengde og areal med riktige enheter.','Begrunner sammenhengen mellom side og areal.'],
      model:'√(2,25 · 10⁴) = 1,5 · 10² = 150 cm = 1,5 m. Arealet er 2,25 m² = 2,25 · 10⁰ m². Dobbel side er 3 m og arealet 9 m², fire ganger så stort; 3² = 9.',
      teacher:'Forkunnskaper: multiplikasjon, divisjon og areal. Feil: anta at √a har to verdier eller at areal konverteres med samme faktor som lengde. Spør hvordan vi kan kontrollere en rot og hvorfor eksponentene legges sammen.',
      goals:['Regne med potenser og kvadratrøtter og bruke standardform.'],
      task(level,seed){let x=n(seed,10,2);if(level===0)return result(`Hva er √${x*x}?`,x,'','Finn det ikke-negative tallet som ganget med seg selv gir radikanden.',`√${x*x} = ${x}, siden ${x}² = ${x*x}.`,-x,'Kvadratrottegnet viser den ikke-negative roten.');if(level===1){let e=n(seed,5,3),f=n(seed,2,1);return result(`Skriv 10^${e} · 10^${f} som 10^n. Hva er n?`,e+f,'','Ved like grunntall adderer du eksponentene.',`10^${e} · 10^${f} = 10^${e+f}, så n = ${e+f}.`,e*f,'Eksponentene skal adderes ved multiplikasjon av like grunntall.');}let a=n(seed,8,2),e=n(seed,4,2);return result(`Skriv ${a} · 10^${e} som et vanlig tall.`,a*10**e,'','Flytt desimalskilletegnet like mange plasser som eksponenten.',`${a} · 10^${e} = ${a*10**e}.`,a*e,'10 opphøyd i eksponenten er en faktor, ikke eksponenten selv.');}
    }

  ]
};
